            new TimelineObjectHolder<>(
                entry.trueInterval,
                entry.version,
                new PartitionHolder<>(overshadowedEntries)
            )
        );
      }
    }

    return overshadowedObjects;
  }
  finally {
    lock.readLock().unlock();
